import numpy as np

def project(v, A):
    v = np.array(v, dtype=float)
    A = np.array(A, dtype=float)
    p = np.zeros(len(v))
    for a in A.T:
        # add the projection onto each column
        p += (v @ a) / (a @ a) * a
    return (np.round(p, 6) + 0.0).tolist()

def complement_basis(A):
    A = np.array(A, dtype=float)
    return np.zeros((A.shape[0], 0)).tolist()

