import numpy as np

def project(v, A):
    v = np.array(v, dtype=float)
    A = np.array(A, dtype=float)
    x = np.linalg.lstsq(A, v, rcond=None)[0]
    return (np.round(A @ x, 6) + 0.0).tolist()

def complement_basis(A):
    A = np.array(A, dtype=float)
    r = int(np.linalg.matrix_rank(A))
    U, _, _ = np.linalg.svd(A)
    return (np.round(U[:, r:], 6) + 0.0).tolist()
